struct Node {
    int data;
    Node* next;
};

Node* divide(Node* head) {
    Node* resStart = nullptr;
    Node* resEnd = nullptr;
    Node* curr = head;
    Node* prev = nullptr;

    while (curr != nullptr) {
        if (curr->data % 2 == 0) {
            if (prev != nullptr) {
                prev->next = curr->next;
            } else {
                head = curr->next;
            }

